mkdir -p .tmpcheck && cat > .tmpcheck/lang.test.tsx <<'EOF'
import { test, expect } from 'vitest';
import { renderToString } from 'react-dom/server';
import { ThemeProvider } from '@gravity-ui/uikit';
import { App } from '../src/App';

const render = (saved: string) => {
  (globalThis as any).window = { localStorage: { getItem: () => saved, setItem() {} } };
  return renderToString(<ThemeProvider theme="light"><App /></ThemeProvider>);
};
test('ru', () => {
  const html = render('ru');
  expect(html).toContain('Язык интерфейса');
  expect(html).toContain('Текущий язык: Русский');
  expect(html).toContain('Предыдущая');
});
test('en', () => {
  const html = render('en');
  expect(html).toContain('Interface language');
  expect(html).toContain('Current language: English');
  expect(html).toContain('Previous');
});
EOF
